{
  "name": "wiki spaces get_node",
  "description": "获取知识空间节点信息",
  "inputSchema": {
    "type": "object",
    "required": [
      "params"
    ],
    "properties": {
      "params": {
        "type": "object",
        "required": [
          "token"
        ],
        "properties": {
          "obj_type": {
            "type": "string",
            "description": "文档类型。不传时默认以 wiki 类型查询",
            "flag": "--obj-type",
            "enum": [
              "doc",
              "docx",
              "sheet",
              "mindnote",
              "bitable",
              "file",
              "slides",
              "wiki"
            ],
            "enumDescriptions": [
              "旧版文档",
              "新版文档",
              "表格",
              "思维导图",
              "多维表格",
              "文件",
              "幻灯片",
              "知识库节点"
            ],
            "default": "wiki",
            "example": "docx"
          },
          "token": {
            "type": "string",
            "description": "知识库节点或对应云文档的实际 token。;- 知识库节点 token：如果 URL 链接中 token 前为 wiki，该 token 为知识库的节点 token。;- 云文档实际 token：如果 URL 链接中 token 前为 docx、base、sheets 等非 wiki 类型，则说明该 token 是当前云文档的实际 token。; 了解更多，请参考[文档常见问题-如何获取云文档资源相关 token（id）](https://open.feishu.cn/document/ukTMukTMukTM/uczNzUjL3czM14yN3MTN)。; 注意：; 使用云文档 token 查询时，需要对 obj_type 参数传入文档对应的类型",
            "flag": "--token",
            "default": "",
            "example": "wikcnKQ1k3p******8Vabcef"
          }
        }
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "node": {
        "type": "object",
        "description": "节点信息",
        "required": [
          "node_type",
          "obj_type"
        ],
        "properties": {
          "creator": {
            "type": "string",
            "description": "文档创建者",
            "example": "ou_xxxxx"
          },
          "has_child": {
            "type": "boolean",
            "description": "是否有子节点",
            "example": false
          },
          "node_create_time": {
            "type": "string",
            "description": "节点创建时间",
            "example": "1642402428"
          },
          "node_creator": {
            "type": "string",
            "description": "节点创建者",
            "example": "ou_xxxxx"
          },
          "node_token": {
            "type": "string",
            "description": "知识库节点 token，如果 URL 链接中 token 前为 wiki，该 token 为知识库的节点 token",
            "example": "wikcnKQ1k3p******8Vabcef"
          },
          "node_type": {
            "type": "string",
            "description": "节点类型",
            "enum": [
              "origin",
              "shortcut"
            ],
            "enumDescriptions": [
              "实体",
              "快捷方式"
            ],
            "example": "origin"
          },
          "obj_create_time": {
            "type": "string",
            "description": "文档创建时间",
            "example": "1642402428"
          },
          "obj_edit_time": {
            "type": "string",
            "description": "文档最近编辑时间",
            "example": "1642402428"
          },
          "obj_token": {
            "type": "string",
            "description": "节点的实际云文档的 token，如果 URL 链接中 token 前为 docx、base、sheets 等非 wiki 类型，则说明该 token 是当前云文档的实际 token。如果要获取或编辑节点内容，需要使用此 token 调用对应的接口。可根据 obj_type 判断属于哪种文档类型",
            "example": "doccnzAaOD******Wabcdef"
          },
          "obj_type": {
            "type": "string",
            "description": "文档类型，对于快捷方式，该字段是对应的实体的obj_type",
            "enum": [
              "doc",
              "sheet",
              "mindnote",
              "bitable",
              "file",
              "docx",
              "slides"
            ],
            "enumDescriptions": [
              "旧版文档",
              "表格",
              "思维导图",
              "多维表格",
              "文件",
              "新版文档",
              "幻灯片"
            ],
            "example": "doc"
          },
          "origin_node_token": {
            "type": "string",
            "description": "快捷方式对应的实体node_token，当节点为快捷方式时，该值不为空",
            "example": "wikcnKQ1k3p******8Vabcef"
          },
          "origin_space_id": {
            "type": "string",
            "description": "快捷方式对应的实体所在的space id",
            "example": "6946843325487912356"
          },
          "owner": {
            "type": "string",
            "description": "文档所有者",
            "example": "ou_xxxxx"
          },
          "parent_node_token": {
            "type": "string",
            "description": "父节点 token。若当前节点为一级节点，父节点 token 为空",
            "example": "wikcnKQ1k3p******8Vabcef"
          },
          "space_id": {
            "type": "string",
            "description": "知识空间 ID。获取方式参考[知识库概述](https://open.feishu.cn/document/ukTMukTMukTM/uUDN04SN0QjL1QDN/wiki-overview)",
            "example": "6946843325487912356"
          },
          "title": {
            "type": "string",
            "description": "文档标题",
            "example": "标题"
          }
        }
      }
    }
  },
  "_meta": {
    "envelope_version": "1.0",
    "scopes": [
      "wiki:wiki",
      "wiki:wiki:readonly",
      "wiki:node:read"
    ],
    "required_scopes": [],
    "access_tokens": [
      "bot",
      "user"
    ],
    "danger": false,
    "risk": "read",
    "doc_url": "https://open.feishu.cn/document/ukTMukTMukTM/uUDN04SN0QjL1QDN/wiki-v2/space/get_node"
  }
}

{
  "name": "im chat.members get",
  "description": "获取群成员列表。Identity: supports `user` and `bot`; the caller must be in the target chat and must belong to the same tenant for internal chats",
  "inputSchema": {
    "type": "object",
    "required": [
      "params"
    ],
    "properties": {
      "params": {
        "type": "object",
        "required": [
          "chat_id"
        ],
        "properties": {
          "chat_id": {
            "type": "string",
            "description": "群 ID。获取方式：; - [创建群](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/chat/create)，从返回结果中获取该群的 chat_id。;- 调用[获取用户或机器人所在的群列表](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/chat/list)接口，可以查询用户或机器人所在群的 chat_id。;- 调用[搜索对用户或机器人可见的群列表](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/chat/search)，可搜索用户或机器人所在的群、对用户或机器人公开的群的 chat_id",
            "flag": "--chat-id",
            "example": "oc_a0553eda9014c201e6969b478895c230"
          },
          "check_security_conf": {
            "type": "boolean",
            "description": "是否检查安全配置",
            "flag": "--check-security-conf"
          },
          "member_id_type": {
            "type": "string",
            "description": "用户 ID 类型",
            "flag": "--member-id-type",
            "enum": [
              "user_id",
              "union_id",
              "open_id"
            ],
            "enumDescriptions": [
              "标识一个用户在某个租户内的身份。同一个用户在租户 A 和租户 B 内的 User ID 是不同的。在同一个租户内，一个用户的 User ID 在所有应用（包括商店应用）中都保持一致。User ID 主要用于在不同的应用间打通用户数据。[了解更多：如何获取 User ID？](/ssl:ttdoc/uAjLw4CM/ugTN1YjL4UTN24CO1UjN/trouble-shooting/how-to-obtain-user-id)",
              "标识一个用户在某个应用开发商下的身份。同一用户在同一开发商下的应用中的 Union ID 是相同的，在不同开发商下的应用中的 Union ID 是不同的。通过 Union ID，应用开发商可以把同个用户在多个应用中的身份关联起来。[了解更多：如何获取 Union ID？](/ssl:ttdoc/uAjLw4CM/ugTN1YjL4UTN24CO1UjN/trouble-shooting/how-to-obtain-union-id)",
              "标识一个用户在某个应用中的身份。同一个用户在不同应用中的 Open ID 不同。[了解更多：如何获取 Open ID？](/ssl:ttdoc/uAjLw4CM/ugTN1YjL4UTN24CO1UjN/trouble-shooting/how-to-obtain-openid)"
            ],
            "default": "",
            "example": "open_id"
          },
          "page_size": {
            "type": "integer",
            "description": "分页大小，用来限制一次请求所返回的数据条目数。; - 由于返回的群成员列表会过滤掉机器人成员，因此返回的群成员个数可能会小于指定的 page_size。; - 如果有同一时间加入群的群成员，会一次性返回，这会导致返回的群成员个数可能会大于指定的 page_size",
            "flag": "--page-size"
          },
          "page_token": {
            "type": "string",
            "description": "分页标记，第一次请求不填，表示从头开始遍历；分页查询结果还有更多项时会同时返回新的 page_token，下次遍历可采用该 page_token 获取查询结果",
            "flag": "--page-token",
            "default": "",
            "example": "WWxHTStrOEs5WHZpNktGbU94bUcvMWlxdDUzTWt1OXNrRmlLaGRNVG0yaz0="
          }
        }
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "has_more": {
        "type": "boolean",
        "description": "是否还有更多项",
        "example": true
      },
      "items": {
        "type": "array",
        "description": "成员列表",
        "items": {
          "type": "object",
          "properties": {
            "member_id": {
              "type": "string",
              "description": "成员的用户ID，ID 值与查询参数中的 member_id_type 对应。; 不同 ID 的说明参见 [用户相关的 ID 概念](https://open.feishu.cn/document/home/user-identity-introduction/introduction)",
              "example": "4d7a3c6g"
            },
            "member_id_type": {
              "type": "string",
              "description": "成员的用户 ID 类型，与查询参数中的 member_id_type 相同。取值为：`open_id`、`user_id`、`union_id`其中之一",
              "example": "user_id"
            },
            "name": {
              "type": "string",
              "description": "名字",
              "example": "张三"
            },
            "tenant_key": {
              "type": "string",
              "description": "租户Key，为租户在飞书上的唯一标识，用来换取对应的tenant_access_token，也可以用作租户在应用中的唯一标识",
              "example": "736588c9260f175d"
            }
          }
        }
      },
      "member_total": {
        "type": "integer",
        "description": "成员总数",
        "example": 2
      },
      "page_token": {
        "type": "string",
        "description": "分页标记，当 has_more 为 true 时，会同时返回新的 page_token，否则不返回 page_token",
        "example": "0"
      },
      "security_conf_limit": {
        "type": "integer",
        "description": "安全配置支持的最大查询群成员数量",
        "example": 100
      },
      "trigger_security_conf_limit": {
        "type": "boolean",
        "description": "是否触发了安全配置"
      }
    }
  },
  "_meta": {
    "envelope_version": "1.0",
    "scopes": [
      "im:chat:readonly",
      "im:chat",
      "im:chat.group_info:readonly",
      "im:chat.members:read"
    ],
    "required_scopes": [],
    "access_tokens": [
      "bot",
      "user"
    ],
    "danger": false,
    "risk": "read",
    "doc_url": "https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/chat-members/get"
  }
}

{
  "name": "im messages delete",
  "description": "撤回消息。Identity: supports `user` and `bot`; for `bot` calls, the bot must be in the chat to revoke group messages; to revoke another user's group message, the bot must be the owner, an admin, or the creator; for user P2P recalls, the target user must be within the bot's availability",
  "inputSchema": {
    "type": "object",
    "required": [
      "params"
    ],
    "properties": {
      "params": {
        "type": "object",
        "required": [
          "message_id"
        ],
        "properties": {
          "message_id": {
            "type": "string",
            "description": "待撤回的消息 ID。; ID 获取方式：; ;- 调用[发送消息](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/message/create)接口后，从响应结果的 `message_id` 参数获取。;- 监听[接收消息](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/message/events/receive)事件，当触发该事件后可以从事件体内获取消息的 `message_id`。;- 调用[获取会话历史消息](https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/message/list)接口，从响应结果的 `message_id` 参数获取",
            "flag": "--message-id",
            "example": "om_dc13264520392913993dd051dba21dcf"
          }
        }
      },
      "yes": {
        "type": "boolean",
        "description": "CLI confirmation gate. Must be true to execute; lark-cli rejects with confirmation_required if absent or false. Pass --yes only after the user has explicitly confirmed; not sent to the backend.",
        "flag": "--yes",
        "default": false
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {}
  },
  "_meta": {
    "envelope_version": "1.0",
    "scopes": [
      "im:message:recall",
      "im:message",
      "im:message:send_as_bot"
    ],
    "required_scopes": [],
    "access_tokens": [
      "bot",
      "user"
    ],
    "danger": true,
    "risk": "high-risk-write",
    "doc_url": "https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/im-v1/message/delete"
  }
}

